INSERT OR IGNORE INTO documents(id,kind,draft,published,updated_at,updated_by) VALUES('conferencias-nacimiento-2026','news','{"title":"Conferencias Semestrales 2026 · IPN Nacimiento","description":"Los días 25, 26 y 27 de septiembre se realizarán nuestras Conferencias Semestrales en IPN Nacimiento.","date":"2026-09-07","image":"https://media.ipnchile.cl/eventos/septiembre-2026/conferencias-nacimiento-2026-afiche-1440.webp","thumbnail":"https://media.ipnchile.cl/eventos/septiembre-2026/conferencias-nacimiento-2026-afiche-640.webp","paragraphs":["Compartimos el afiche oficial de las Conferencias Semestrales 2026, que tendrán lugar los días 25, 26 y 27 de septiembre en IPN Nacimiento.","Invitamos a nuestra comunidad a acompañar en oración este encuentro de comunión y fortalecimiento ministerial. Consulte la información del calendario nacional para conocer los datos del evento."],"eventLink":"/actualidad/eventos?evento=5"}','{"title":"Conferencias Semestrales 2026 · IPN Nacimiento","description":"Los días 25, 26 y 27 de septiembre se realizarán nuestras Conferencias Semestrales en IPN Nacimiento.","date":"2026-09-07","image":"https://media.ipnchile.cl/eventos/septiembre-2026/conferencias-nacimiento-2026-afiche-1440.webp","thumbnail":"https://media.ipnchile.cl/eventos/septiembre-2026/conferencias-nacimiento-2026-afiche-640.webp","paragraphs":["Compartimos el afiche oficial de las Conferencias Semestrales 2026, que tendrán lugar los días 25, 26 y 27 de septiembre en IPN Nacimiento.","Invitamos a nuestra comunidad a acompañar en oración este encuentro de comunión y fortalecimiento ministerial. Consulte la información del calendario nacional para conocer los datos del evento."],"eventLink":"/actualidad/eventos?evento=5"}','2026-09-07T12:00:00.000Z','master.ipnchile@gmail.com');
