INSERT OR IGNORE INTO documents(id,kind,draft,published,updated_at,updated_by) VALUES('mes-biblia-patria-2026','news','{"title":"Septiembre: Mes de la Biblia y de la Patria","description":"Un mes para acercarnos a la Palabra de Dios y dar gracias por nuestro país. Conozca por qué celebramos el Mes de la Biblia.","date":"2026-09-07","image":"https://media.ipnchile.cl/eventos/septiembre-2026/mes-de-la-biblia-2026-1086.webp","thumbnail":"https://media.ipnchile.cl/eventos/septiembre-2026/mes-de-la-biblia-2026-640.webp","paragraphs":["En la tradición evangélica de habla hispana, septiembre recuerda la publicación de la Biblia del Oso en 1569, traducida por Casiodoro de Reina. Su revisión por Cipriano de Valera en 1602 forma parte de la historia de la versión Reina-Valera.","El Mes de la Biblia nos invita a leer, estudiar y compartir las Escrituras, y a poner en práctica sus enseñanzas en nuestra vida diaria. Podemos dedicar tiempo a la lectura personal y en familia, a la oración y a la reflexión en comunidad.","En este mes de la Patria, también damos gracias a Dios por Chile y oramos por sus familias, sus comunidades y quienes sirven a nuestro país. Que la Palabra de Dios ilumine nuestro caminar y nos impulse a amar y servir al prójimo."],"source":{"label":"Sociedad Bíblica Chilena: por qué septiembre es el Mes de la Biblia","url":"https://www.sbch.cl/sitio/por-que-septiembre-es-el-mes-de-la-biblia/"}}','{"title":"Septiembre: Mes de la Biblia y de la Patria","description":"Un mes para acercarnos a la Palabra de Dios y dar gracias por nuestro país. Conozca por qué celebramos el Mes de la Biblia.","date":"2026-09-07","image":"https://media.ipnchile.cl/eventos/septiembre-2026/mes-de-la-biblia-2026-1086.webp","thumbnail":"https://media.ipnchile.cl/eventos/septiembre-2026/mes-de-la-biblia-2026-640.webp","paragraphs":["En la tradición evangélica de habla hispana, septiembre recuerda la publicación de la Biblia del Oso en 1569, traducida por Casiodoro de Reina. Su revisión por Cipriano de Valera en 1602 forma parte de la historia de la versión Reina-Valera.","El Mes de la Biblia nos invita a leer, estudiar y compartir las Escrituras, y a poner en práctica sus enseñanzas en nuestra vida diaria. Podemos dedicar tiempo a la lectura personal y en familia, a la oración y a la reflexión en comunidad.","En este mes de la Patria, también damos gracias a Dios por Chile y oramos por sus familias, sus comunidades y quienes sirven a nuestro país. Que la Palabra de Dios ilumine nuestro caminar y nos impulse a amar y servir al prójimo."],"source":{"label":"Sociedad Bíblica Chilena: por qué septiembre es el Mes de la Biblia","url":"https://www.sbch.cl/sitio/por-que-septiembre-es-el-mes-de-la-biblia/"}}','2026-09-07T12:00:00.000Z','master.ipnchile@gmail.com');
